def json_diff(a, b):
    result = {}
    all_keys = set(a.keys()).union(set(b.keys()))
    for key in all_keys:
        val_a = a.get(key, None)
        val_b = b.get(key, None)
        if val_a != val_b:
            result[key] = [val_a, val_b]
    return result
